package campaign_test

import (
	"encoding/json"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/campaign"
)

func TestCampaignMarshalJSON_ComputesRemaining(t *testing.T) {
	c := campaign.Campaign{
		ID:     1,
		Title:  "t",
		Budget: 100,
		Spent:  40,
		Status: campaign.StatusActive,
	}

	data, err := json.Marshal(c)
	require.NoError(t, err)

	var decoded map[string]any
	require.NoError(t, json.Unmarshal(data, &decoded))

	assert.EqualValues(t, 60, decoded["remaining"])
	assert.EqualValues(t, 40, decoded["spent"])
	assert.EqualValues(t, 100, decoded["budget"])
}

func TestCampaignMarshalJSON_NormalizesToUTC(t *testing.T) {
	loc := time.FixedZone("UTC+3", 3*60*60)
	local := time.Date(2026, 9, 18, 3, 0, 0, 0, loc) // same instant as 2026-09-18T00:00:00Z

	c := campaign.Campaign{
		StartDate: local,
		EndDate:   local,
		CreatedAt: local,
		UpdatedAt: local,
	}

	data, err := json.Marshal(c)
	require.NoError(t, err)

	var decoded map[string]any
	require.NoError(t, json.Unmarshal(data, &decoded))

	for _, field := range []string{"start_date", "end_date", "created_at", "updated_at"} {
		assert.Equal(t, "2026-09-18T00:00:00Z", decoded[field], "field %s should be normalized to UTC", field)
	}
}

func TestCampaignMarshalJSON_DoesNotRecurse(t *testing.T) {
	// Regression guard: a naive MarshalJSON embedding Campaign directly (instead
	// of a defined `type Alias Campaign`) would recurse infinitely. This just
	// needs to complete without a stack overflow/panic.
	assert.NotPanics(t, func() {
		_, err := json.Marshal(campaign.Campaign{Budget: 10, Spent: 5})
		require.NoError(t, err)
	})
}

func TestCampaignStats(t *testing.T) {
	c := campaign.Campaign{
		Budget: 100,
		Spent:  30,
		Status: campaign.StatusPaused,
	}

	stats := c.Stats()

	assert.Equal(t, int64(30), stats.Impressions, "impressions must equal spent")
	assert.Equal(t, int64(30), stats.Spent)
	assert.Equal(t, int64(70), stats.Remaining)
	assert.Equal(t, int64(100), stats.Budget)
	assert.Equal(t, campaign.StatusPaused, stats.Status)
}

