)

func TestConstructors(t *testing.T) {
	cases := []struct {
		name       string
		err        *httpx.AppError
		wantStatus int
	}{
		{"Invalid", httpx.Invalid("bad input"), http.StatusBadRequest},
		{"NotFound", httpx.NotFound("missing"), http.StatusNotFound},
		{"Conflict", httpx.Conflict("conflict"), http.StatusConflict},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			assert.Equal(t, tc.wantStatus, tc.err.Status)
			assert.NotEmpty(t, tc.err.Message)
			assert.Equal(t, tc.err.Message, tc.err.Error())
		})
	}
}

func TestWriteJSON(t *testing.T) {
	w := httptest.NewRecorder()

	httpx.WriteJSON(w, http.StatusCreated, map[string]string{"hello": "world"})

	assert.Equal(t, http.StatusCreated, w.Code)
	assert.Equal(t, "application/json", w.Header().Get("Content-Type"))

