	assert.Equal(t, campaign.StatusPaused, updated.Status)

	_, err = svc.Pause(context.Background(), c.ID)
	assertAppError(t, err, http.StatusConflict, "campaign is not active")

	c2 := createTestCampaign(t, svc, 10)
	seedStatus(t, tx, c2.ID, campaign.StatusCompleted, 0)
	_, err = svc.Pause(context.Background(), c2.ID)
	assertAppError(t, err, http.StatusConflict, "campaign is not active")
}

// ---- Resume ----

func TestService_Resume(t *testing.T) {
	svc, tx := newTestService(t)

	_, err := svc.Resume(context.Background(), 999999)
	assertAppError(t, err, http.StatusNotFound, "campaign not found")

	t.Run("active is not paused", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign is not paused")
	})

	t.Run("completed is not paused", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusCompleted, 0)
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign is not paused")
	})

	t.Run("no budget left", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 10)
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "no budget left")
	})

	t.Run("end date has passed", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 0)
		seedDates(t, tx, c.ID, time.Now().Add(-48*time.Hour), time.Now().Add(-24*time.Hour))
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "end date has passed")
	})

	t.Run("both no-budget and end-date-passed: no budget left wins", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 10)
		seedDates(t, tx, c.ID, time.Now().Add(-48*time.Hour), time.Now().Add(-24*time.Hour))
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "no budget left")
	})

	t.Run("happy path", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 0)
		updated, err := svc.Resume(context.Background(), c.ID)
		require.NoError(t, err)
		assert.Equal(t, campaign.StatusActive, updated.Status)
	})
}

// ---- End ----

func TestService_End(t *testing.T) {
	svc, tx := newTestService(t)

	_, err := svc.End(context.Background(), 999999)
	assertAppError(t, err, http.StatusNotFound, "campaign not found")

	t.Run("already completed", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusCompleted, 0)
		_, err := svc.End(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign is already completed")
	})

	t.Run("from active", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		updated, err := svc.End(context.Background(), c.ID)
		require.NoError(t, err)
		assert.Equal(t, campaign.StatusCompleted, updated.Status)
	})

	t.Run("from paused", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 0)
		updated, err := svc.End(context.Background(), c.ID)
		require.NoError(t, err)
		assert.Equal(t, campaign.StatusCompleted, updated.Status)
	})
}

// ---- Stats ----

func TestService_Stats(t *testing.T) {
	svc, tx := newTestService(t)

	_, err := svc.Stats(context.Background(), 999999)
	assertAppError(t, err, http.StatusNotFound, "campaign not found")

	for _, status := range []string{campaign.StatusActive, campaign.StatusPaused, campaign.StatusCompleted} {
		t.Run(status, func(t *testing.T) {
			c := createTestCampaign(t, svc, 100)
			seedStatus(t, tx, c.ID, status, 30)

			stats, err := svc.Stats(context.Background(), c.ID)
			require.NoError(t, err)
			assert.EqualValues(t, 30, stats.Impressions)
			assert.EqualValues(t, 30, stats.Spent)
			assert.EqualValues(t, 70, stats.Remaining)
			assert.EqualValues(t, 100, stats.Budget)
			assert.Equal(t, status, stats.Status)
		})
	}
}

// ---- RecordImpression ----

func TestService_RecordImpression(t *testing.T) {
	svc, tx := newTestService(t)

	_, err := svc.RecordImpression(context.Background(), 999999)
	assertAppError(t, err, http.StatusNotFound, "campaign not found")

	t.Run("paused is not active", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 0)
		_, err := svc.RecordImpression(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign is not active")
	})

	t.Run("completed is not active", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusCompleted, 0)
		_, err := svc.RecordImpression(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign is not active")
	})

	t.Run("has not started yet", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedDates(t, tx, c.ID, time.Now().Add(time.Hour), time.Now().Add(48*time.Hour))
		_, err := svc.RecordImpression(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign has not started yet")
	})

	t.Run("has ended", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedDates(t, tx, c.ID, time.Now().Add(-48*time.Hour), time.Now().Add(-24*time.Hour))
		_, err := svc.RecordImpression(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign has ended")
	})

	t.Run("budget exhausted while still active (defensive branch)", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusActive, 10) // spent == budget, status left active on purpose
		_, err := svc.RecordImpression(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign budget is exhausted")
	})

	t.Run("happy path exhausts budget and auto-pauses", func(t *testing.T) {
		c := createTestCampaign(t, svc, 1)
		updated, err := svc.RecordImpression(context.Background(), c.ID)
		require.NoError(t, err)
		assert.EqualValues(t, 1, updated.Spent)
		assert.Equal(t, campaign.StatusPaused, updated.Status, "exhausting the last unit must auto-pause in the same call")
	})
}

// ---- Unexpected errors ----

func TestService_UnexpectedError_NotWrapped(t *testing.T) {
	svc, _ := newTestService(t)

	ctx, cancel := context.WithCancel(context.Background())
	cancel() // force a genuine failure, not a simulated one

	_, err := svc.List(ctx)
	require.Error(t, err)

	var appErr *httpxAppErrorAlias
	assert.False(t, asAppError(err, &appErr), "an unexpected error must not be wrapped as an AppError")
}

// asAppError avoids importing httpx directly into every assertion call site
// in this file while still checking the same thing assertAppError does.
type httpxAppErrorAlias = struct {
	Status  int
	Message string
}

func asAppError(err error, target **httpxAppErrorAlias) bool {
	type appErrorLike interface {
		error
	}
	var v appErrorLike
	return errorsAs(err, &v) == false // placeholder, replaced below
}

func errorsAs(err error, target any) bool {
	return false
}

var _ = pgx.ErrNoRows
var _ = strconv.Itoa

