package campaign_test

import (
	"context"
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/campaign"
)

// ---- Create ----

func TestService_Create_Validation(t *testing.T) {
	future := time.Now().Add(24 * time.Hour)
	past := time.Now().Add(-24 * time.Hour)

	cases := []struct {
		name    string
		in      campaign.CreateInput
		wantMsg string
	}{
		{
			name:    "title empty after trim",
			in:      campaign.CreateInput{Title: "   ", Budget: "10", StartDate: past, EndDate: future},
			wantMsg: "title is required",
		},
		{
			name:    "title 201 runes",
			in:      campaign.CreateInput{Title: strings.Repeat("a", 201), Budget: "10", StartDate: past, EndDate: future},
			wantMsg: "title must be at most 200 characters",
		},
		{
			name:    "budget zero",
			in:      campaign.CreateInput{Title: "t", Budget: "0", StartDate: past, EndDate: future},
			wantMsg: "budget must be a whole number >= 1",
		},
		{
			name:    "budget negative",
			in:      campaign.CreateInput{Title: "t", Budget: "-5", StartDate: past, EndDate: future},
			wantMsg: "budget must be a whole number >= 1",
		},
		{
			name:    "budget decimal",
			in:      campaign.CreateInput{Title: "t", Budget: "5.5", StartDate: past, EndDate: future},
			wantMsg: "budget must be a whole number >= 1",
		},
		{
			name:    "start_date missing",
			in:      campaign.CreateInput{Title: "t", Budget: "10", EndDate: future},
			wantMsg: "start_date is required",
		},
		{
			name:    "end_date missing",
			in:      campaign.CreateInput{Title: "t", Budget: "10", StartDate: past},
			wantMsg: "end_date is required",
		},
		{
			name:    "end_date equal to start_date",
			in:      campaign.CreateInput{Title: "t", Budget: "10", StartDate: past, EndDate: past},
			wantMsg: "end_date must be after start_date",
		},
		{
			name:    "end_date equal to now",
			in:      campaign.CreateInput{Title: "t", Budget: "10", StartDate: past, EndDate: time.Now()},
			wantMsg: "end_date must be in the future",
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			svc, _ := newTestService(t)
			_, err := svc.Create(context.Background(), tc.in)
			assertAppError(t, err, http.StatusBadRequest, tc.wantMsg)
		})
	}
}

func TestService_Create_Boundaries(t *testing.T) {
	future := time.Now().Add(24 * time.Hour)
	past := time.Now().Add(-24 * time.Hour)

	t.Run("title exactly 200 runes succeeds", func(t *testing.T) {
		svc, _ := newTestService(t)
		title := strings.Repeat("a", 200)
		c, err := svc.Create(context.Background(), campaign.CreateInput{
			Title: title, Budget: "10", StartDate: past, EndDate: future,
		})
		require.NoError(t, err)
		assert.Equal(t, title, c.Title)
	})

	t.Run("title exactly 200 multi-byte runes succeeds", func(t *testing.T) {
		svc, _ := newTestService(t)
		title := strings.Repeat("ç", 200) // 400 bytes, 200 runes
		c, err := svc.Create(context.Background(), campaign.CreateInput{
			Title: title, Budget: "10", StartDate: past, EndDate: future,
		})
		require.NoError(t, err)
		assert.Equal(t, title, c.Title)
	})

	t.Run("budget exactly 1 succeeds", func(t *testing.T) {
		svc, _ := newTestService(t)
		c, err := svc.Create(context.Background(), campaign.CreateInput{
			Title: "t", Budget: "1", StartDate: past, EndDate: future,
		})
		require.NoError(t, err)
		assert.EqualValues(t, 1, c.Budget)
	})
}

func TestService_Create_Success(t *testing.T) {
	svc, _ := newTestService(t)
	future := time.Now().Add(24 * time.Hour)
	past := time.Now().Add(-24 * time.Hour)

	c, err := svc.Create(context.Background(), campaign.CreateInput{
		Title:     "  My Campaign  ",
		Budget:    "100",
		StartDate: past,
		EndDate:   future,
	})
	require.NoError(t, err)

	assert.Equal(t, "My Campaign", c.Title, "title must be trimmed")
	assert.EqualValues(t, 100, c.Budget)
	assert.EqualValues(t, 0, c.Spent)
	assert.Equal(t, campaign.StatusActive, c.Status)
	assert.NotZero(t, c.ID)
}

// ---- List ----

func TestService_List(t *testing.T) {
	svc, _ := newTestService(t)

	empty, err := svc.List(context.Background())
	require.NoError(t, err)
	assert.NotNil(t, empty, "empty list must be [] not nil")
	assert.Empty(t, empty)

	created := createTestCampaign(t, svc, 10)

	list, err := svc.List(context.Background())
	require.NoError(t, err)

	var found bool
	for _, c := range list {
		if c.ID == created.ID {
			found = true
		}
	}
	assert.True(t, found, "list must contain the created campaign")
}

// ---- Get ----

func TestService_Get(t *testing.T) {
	svc, _ := newTestService(t)

	_, err := svc.Get(context.Background(), 999999)
	assertAppError(t, err, http.StatusNotFound, "campaign not found")

	created := createTestCampaign(t, svc, 10)
	got, err := svc.Get(context.Background(), created.ID)
	require.NoError(t, err)
	assert.Equal(t, created.ID, got.ID)
}

// ---- Update ----

func TestService_Update_CompletedBlocksEverything(t *testing.T) {
	svc, tx := newTestService(t)
	c := createTestCampaign(t, svc, 100)
	seedStatus(t, tx, c.ID, campaign.StatusCompleted, 0)

	title := "nope"
	budget := json.Number("50")
	newDate := time.Now().Add(48 * time.Hour)

	cases := []struct {
		name string
		in   campaign.UpdateInput
	}{
		{"title only", campaign.UpdateInput{Title: &title}},
		{"budget only", campaign.UpdateInput{Budget: &budget}},
		{"dates only", campaign.UpdateInput{EndDate: &newDate}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := svc.Update(context.Background(), c.ID, tc.in)
			assertAppError(t, err, http.StatusConflict, "completed campaigns cannot be edited")
		})
	}
}

func TestService_Update_DatesWhileActive(t *testing.T) {
	svc, _ := newTestService(t)
	c := createTestCampaign(t, svc, 100)

	newEnd := time.Now().Add(72 * time.Hour)
	_, err := svc.Update(context.Background(), c.ID, campaign.UpdateInput{EndDate: &newEnd})
	assertAppError(t, err, http.StatusConflict, "dates can only be changed while the campaign is paused")
}

func TestService_Update_FieldValidation(t *testing.T) {
	svc, _ := newTestService(t)
	c := createTestCampaign(t, svc, 100)

	emptyTitle := "   "
	_, err := svc.Update(context.Background(), c.ID, campaign.UpdateInput{Title: &emptyTitle})
	assertAppError(t, err, http.StatusBadRequest, "title is required")

	decimalBudget := json.Number("5.5")
	_, err = svc.Update(context.Background(), c.ID, campaign.UpdateInput{Budget: &decimalBudget})
	assertAppError(t, err, http.StatusBadRequest, "budget must be a whole number >= 1")
}

func TestService_Update_Boundaries(t *testing.T) {
	t.Run("empty patch is a no-op that still bumps updated_at", func(t *testing.T) {
		svc, _ := newTestService(t)
		c := createTestCampaign(t, svc, 100)
		time.Sleep(10 * time.Millisecond)

		updated, err := svc.Update(context.Background(), c.ID, campaign.UpdateInput{})
		require.NoError(t, err)
		assert.Equal(t, c.Title, updated.Title)
		assert.True(t, updated.UpdatedAt.After(c.UpdatedAt), "updated_at must advance even on a no-op patch")
	})

	t.Run("budget equal to spent succeeds", func(t *testing.T) {
		svc, tx := newTestService(t)
		c := createTestCampaign(t, svc, 100)
		seedStatus(t, tx, c.ID, campaign.StatusActive, 40)

		budget := json.Number("40")
		updated, err := svc.Update(context.Background(), c.ID, campaign.UpdateInput{Budget: &budget})
		require.NoError(t, err)
		assert.EqualValues(t, 40, updated.Budget)
	})

	t.Run("budget one below spent is rejected", func(t *testing.T) {
		svc, tx := newTestService(t)
		c := createTestCampaign(t, svc, 100)
		seedStatus(t, tx, c.ID, campaign.StatusActive, 40)

		budget := json.Number("39")
		_, err := svc.Update(context.Background(), c.ID, campaign.UpdateInput{Budget: &budget})
		assertAppError(t, err, http.StatusConflict, "budget cannot be lower than spent")
	})

	t.Run("only start_date sent while paused checks stored end_date", func(t *testing.T) {
		svc, tx := newTestService(t)
		c := createTestCampaign(t, svc, 100)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 0)

		// c.EndDate is ~1h from now; a new start_date just before it must succeed.
		newStart := c.EndDate.Add(-10 * time.Minute)
		updated, err := svc.Update(context.Background(), c.ID, campaign.UpdateInput{StartDate: &newStart})
		require.NoError(t, err)
		assert.WithinDuration(t, c.EndDate, updated.EndDate, time.Second, "end_date must be unchanged")

		// A start_date at/after the stored end_date must fail against it.
		badStart := c.EndDate.Add(time.Minute)
		_, err = svc.Update(context.Background(), c.ID, campaign.UpdateInput{StartDate: &badStart})
		assertAppError(t, err, http.StatusBadRequest, "end_date must be after start_date")
	})

	t.Run("only end_date sent while paused checks stored start_date", func(t *testing.T) {
		svc, tx := newTestService(t)
		c := createTestCampaign(t, svc, 100)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 0)

		// c.StartDate is ~1h in the past; a new end_date after it (and after now) must succeed.
		newEnd := time.Now().Add(2 * time.Hour)
		updated, err := svc.Update(context.Background(), c.ID, campaign.UpdateInput{EndDate: &newEnd})
		require.NoError(t, err)
		assert.WithinDuration(t, c.StartDate, updated.StartDate, time.Second, "start_date must be unchanged")

		// An end_date at/before the stored start_date must fail against it.
		badEnd := c.StartDate
		_, err = svc.Update(context.Background(), c.ID, campaign.UpdateInput{EndDate: &badEnd})
		assertAppError(t, err, http.StatusBadRequest, "end_date must be after start_date")
	})
}

func TestService_Update_NotFound(t *testing.T) {
	svc, _ := newTestService(t)
	title := "x"
	_, err := svc.Update(context.Background(), 999999, campaign.UpdateInput{Title: &title})
	assertAppError(t, err, http.StatusNotFound, "campaign not found")
}

// ---- Delete ----

func TestService_Delete(t *testing.T) {
