// ---- Pause ----

func TestService_Pause(t *testing.T) {
	svc, tx := newTestService(t)

	_, err := svc.Pause(context.Background(), 999999)
	assertAppError(t, err, http.StatusNotFound, "campaign not found")

	c := createTestCampaign(t, svc, 10)
	updated, err := svc.Pause(context.Background(), c.ID)
