// ---- Resume ----

func TestService_Resume(t *testing.T) {
	svc, tx := newTestService(t)

	_, err := svc.Resume(context.Background(), 999999)
	assertAppError(t, err, http.StatusNotFound, "campaign not found")

	t.Run("active is not paused", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign is not paused")
	})

	t.Run("completed is not paused", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusCompleted, 0)
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign is not paused")
	})

	t.Run("no budget left", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 10)
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "no budget left")
	})

	t.Run("end date has passed", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 0)
		seedDates(t, tx, c.ID, time.Now().Add(-48*time.Hour), time.Now().Add(-24*time.Hour))
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "end date has passed")
	})

	t.Run("both no-budget and end-date-passed: no budget left wins", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 10)
		seedDates(t, tx, c.ID, time.Now().Add(-48*time.Hour), time.Now().Add(-24*time.Hour))
		_, err := svc.Resume(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "no budget left")
	})

	t.Run("happy path", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 0)
		updated, err := svc.Resume(context.Background(), c.ID)
		require.NoError(t, err)
		assert.Equal(t, campaign.StatusActive, updated.Status)
	})
}

// ---- End ----

func TestService_End(t *testing.T) {
	svc, tx := newTestService(t)

	_, err := svc.End(context.Background(), 999999)
	assertAppError(t, err, http.StatusNotFound, "campaign not found")

	t.Run("already completed", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusCompleted, 0)
		_, err := svc.End(context.Background(), c.ID)
		assertAppError(t, err, http.StatusConflict, "campaign is already completed")
	})

	t.Run("from active", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		updated, err := svc.End(context.Background(), c.ID)
		require.NoError(t, err)
		assert.Equal(t, campaign.StatusCompleted, updated.Status)
	})

	t.Run("from paused", func(t *testing.T) {
		c := createTestCampaign(t, svc, 10)
		seedStatus(t, tx, c.ID, campaign.StatusPaused, 0)
		updated, err := svc.End(context.Background(), c.ID)
		require.NoError(t, err)
		assert.Equal(t, campaign.StatusCompleted, updated.Status)
	})
}

