package campaign_test

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"strconv"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/campaign"
	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/httpx"
)

// assertAppError fails the test unless err is an *httpx.AppError with the
// exact status/message expected — the shape every service method's failure
// path is supposed to produce (never a raw/unwrapped error for known cases).
func assertAppError(t *testing.T, err error, wantStatus int, wantMessage string) {
	t.Helper()
	var appErr *httpx.AppError
	if !assert.ErrorAs(t, err, &appErr) {
		return
	}
	assert.Equal(t, wantStatus, appErr.Status)
	assert.Equal(t, wantMessage, appErr.Message)
}

// newTestTx opens a fresh pool and begins a transaction that is rolled back
// via t.Cleanup no matter what happens in the test — nothing it writes is
// ever visible to any other connection, and nothing survives once it ends.
// Skips if DATABASE_URL isn't set, same convention as impression_test.go.
func newTestTx(t *testing.T) pgx.Tx {
	t.Helper()

	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		t.Skip("DATABASE_URL not set; run against the Postgres started by docker compose")
	}

	ctx := context.Background()
	pool, err := pgxpool.New(ctx, databaseURL)
	require.NoError(t, err)
	t.Cleanup(pool.Close)

	tx, err := pool.Begin(ctx)
	require.NoError(t, err)
	t.Cleanup(func() { _ = tx.Rollback(ctx) })

	return tx
}

// newTestService returns a Service plus the underlying pgx.Tx it's built on,
// so tests can seed fixture states (paused/completed/a specific spent) via
// raw SQL on that same transaction — states the public API can't otherwise
// produce yet, without leaving any trace once the transaction rolls back.
func newTestService(t *testing.T) (*campaign.Service, pgx.Tx) {
	t.Helper()
	tx := newTestTx(t)
	return campaign.NewService(campaign.NewRepository(tx)), tx
}

func newTestServer(t *testing.T) (*httptest.Server, pgx.Tx) {
	t.Helper()
	svc, tx := newTestService(t)
	h := campaign.NewHandler(svc)
	mux := http.NewServeMux()
	campaign.RegisterRoutes(mux, h)
	server := httptest.NewServer(mux)
	t.Cleanup(server.Close)
	return server, tx
}

// seedStatus directly sets a campaign's status/spent on the test's own
// transaction, bypassing every application-level invariant — used to reach
// states the public API can't produce (paused/completed, a specific spent),
// exactly like the docker-exec-psql fixtures used during manual testing,
// just against this test's own isolated, rolled-back transaction instead.
func seedStatus(t *testing.T, tx pgx.Tx, id int64, status string, spent int64) {
	t.Helper()
	_, err := tx.Exec(context.Background(),
		"UPDATE campaigns SET status = $2, spent = $3 WHERE id = $1", id, status, spent)
	require.NoError(t, err)
}

// seedDates directly sets a campaign's start/end dates on the test's own
// transaction, for reaching date-window states the public API restricts.
func seedDates(t *testing.T, tx pgx.Tx, id int64, start, end time.Time) {
	t.Helper()
	_, err := tx.Exec(context.Background(),
		"UPDATE campaigns SET start_date = $2, end_date = $3 WHERE id = $1", id, start, end)
	require.NoError(t, err)
}

// createTestCampaign creates a valid, immediately-deductible active campaign
// (start_date in the past, end_date in the future) via the real Create path.
func createTestCampaign(t *testing.T, svc *campaign.Service, budget int64) campaign.Campaign {
	t.Helper()
	c, err := svc.Create(context.Background(), campaign.CreateInput{
		Title:     "test campaign",
		Budget:    json.Number(strconv.FormatInt(budget, 10)),
		StartDate: time.Now().Add(-time.Hour),
		EndDate:   time.Now().Add(time.Hour),
	})
	require.NoError(t, err)
	return c
}

